import React from 'react';
import { ExpandableTile, TileAboveTheFoldContent, TileBelowTheFoldContent } from '@carbon/react';
import { StructuredListWrapper, StructuredListHead, StructuredListBody, StructuredListRow, StructuredListCell } from '@carbon/react';

function ExpandableTileWithStructuredList() {
  return (
    <ExpandableTile
      id="expandable-tile-1"
      tabIndex={0}
      expanded={false} // This is where the aria-expanded issue occurs
    >
      <TileAboveTheFoldContent>
        <div>Above the fold content</div>
      </TileAboveTheFoldContent>
      <TileBelowTheFoldContent>
        <StructuredListWrapper>
          <StructuredListHead>
            <StructuredListRow head>
              <StructuredListCell head>ColumnA</StructuredListCell>
              <StructuredListCell head>ColumnB</StructuredListCell>
            </StructuredListRow>
          </StructuredListHead>
          <StructuredListBody>
            <StructuredListRow>
              <StructuredListCell noWrap>Row 1</StructuredListCell>
              <StructuredListCell>Row 1</StructuredListCell>
            </StructuredListRow>
          </StructuredListBody>
        </StructuredListWrapper>
      </TileBelowTheFoldContent>
    </ExpandableTile>
  );
}

export default ExpandableTileWithStructuredList;
